import{_ as t,o as r,c as a,ao as i}from"./chunks/framework.C1_8nBam.js";const u=JSON.parse('{"title":"Attribution and license","description":"","frontmatter":{},"headers":[],"relativePath":"attribution.md","filePath":"attribution.md","lastUpdated":null}'),o={name:"attribution.md"};function n(s,e,l,d,h,p){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="Attribution-and-license" tabindex="-1">Attribution and license <a class="header-anchor" href="#Attribution-and-license" aria-label="Permalink to &quot;Attribution and license {#Attribution-and-license}&quot;">​</a></h1><p>Four packages, two licenses. What each one derives from differs, and so does the license it carries.</p><table tabindex="0"><thead><tr><th style="text-align:right;">package</th><th style="text-align:right;">license</th><th style="text-align:right;">derives from</th></tr></thead><tbody><tr><td style="text-align:right;"><code>PureQPBase</code></td><td style="text-align:right;">MIT</td><td style="text-align:right;">published papers only</td></tr><tr><td style="text-align:right;"><code>PureIPM</code></td><td style="text-align:right;">MIT</td><td style="text-align:right;">published papers only</td></tr><tr><td style="text-align:right;"><code>PureDAQP</code></td><td style="text-align:right;">MIT</td><td style="text-align:right;">a paper and <a href="https://github.com/darnstrom/daqp" target="_blank" rel="noreferrer">DAQP</a>, which is MIT</td></tr><tr><td style="text-align:right;"><code>PureOSQP</code></td><td style="text-align:right;">Apache-2.0</td><td style="text-align:right;"><a href="https://osqp.org" target="_blank" rel="noreferrer">OSQP</a>, and carries its license</td></tr></tbody></table><p><strong>Depending on a package does not place yours under its license.</strong> Using <code>PureQPBase</code> leaves your package under whatever license you choose, and <code>PureOSQP</code> depending on <code>PureQPBase</code> does not place <code>PureQPBase</code> under Apache-2.0. Only a derivative work carries its parent&#39;s terms, and a dependency is not a derivative.</p><p>Each package directory carries the license governing it — <code>PureQPBase/LICENSE</code>, <code>PureIPM/LICENSE</code>, <code>PureDAQP/LICENSE</code>, <code>PureOSQP/LICENSE</code>. The <code>LICENSE</code> at the repository root is a map to those four rather than a license itself, since claiming either one there would be wrong for three of the packages. Everything outside the four package directories — the shared benchmarks, this documentation, the design notes — is MIT.</p><h2 id="PureOSQP" tabindex="-1">PureOSQP <a class="header-anchor" href="#PureOSQP" aria-label="Permalink to &quot;PureOSQP {#PureOSQP}&quot;">​</a></h2><p><strong>This is not a clean-room implementation.</strong> The operator-splitting method was written using the OSQP paper and the reference C implementation, for details such as the <code>ρ</code> update schedule and the order of the iteration. OSQP&#39;s C unit tests were ported into the test suite.</p><p>It is therefore a derivative work and is released under <strong>Apache-2.0</strong>, matching upstream. That is not a preference: a derivative carries its parent&#39;s terms.</p><ul><li><p>Website: <a href="https://osqp.org" target="_blank" rel="noreferrer">https://osqp.org</a></p></li><li><p>Source: <a href="https://github.com/osqp/osqp" target="_blank" rel="noreferrer">https://github.com/osqp/osqp</a> (Apache-2.0)</p></li><li><p>Copyright: the OSQP authors.</p></li><li><p>C library: Bartolomeo Stellato, Goran Banjac, and Paul Goulart.</p></li></ul><p><a href="https://github.com/osqp/OSQP.jl" target="_blank" rel="noreferrer">OSQP.jl</a> (Twan Koolen, Benoît Legat, and Bartolomeo Stellato) is the independent implementation used to validate it.</p><h2 id="PureQPBase" tabindex="-1">PureQPBase <a class="header-anchor" href="#PureQPBase" aria-label="Permalink to &quot;PureQPBase {#PureQPBase}&quot;">​</a></h2><p><strong>MIT.</strong> The core is not a derivative of OSQP. It was written from the published descriptions of the methods it implements:</p><p><strong>Equilibration:</strong> <a href="https://ral.ac.uk/Publications/RAL-TR-2001-034.pdf" target="_blank" rel="noreferrer">A scaling algorithm to equilibrate both rows and columns norms in matrices</a> (Ruiz, 2001).</p><p><strong>Infeasibility certificates:</strong> <a href="https://doi.org/10.1007/s10957-019-01575-y" target="_blank" rel="noreferrer">Infeasibility detection in the alternating direction method of multipliers for convex optimization</a> (Banjac et al., 2019). The certificate tests hold for any direction, whatever produced it, which is why operator splitting and the interior-point method use them unchanged.</p><p>The linear-system backends, the backend selection, the problem representation and the polishing and derivative kernels are this package&#39;s own.</p><h2 id="PureDAQP" tabindex="-1">PureDAQP <a class="header-anchor" href="#PureDAQP" aria-label="Permalink to &quot;PureDAQP {#PureDAQP}&quot;">​</a></h2><p><strong>MIT.</strong> The method is Algorithm 1 of <a href="https://doi.org/10.1109/TAC.2022.3176430" target="_blank" rel="noreferrer">A dual active-set solver for embedded quadratic programming using recursive LDLᵀ updates</a> (Arnström, Bemporad and Axehill, 2022), with that paper&#39;s Algorithm 2 as the proximal-point outer loop.</p><p><strong>This is not a clean-room implementation.</strong> The authors&#39; reference C implementation was read alongside the paper, for details the paper leaves to the implementer: the pivoting rule, the anti-cycling switch, and the way the <code>LDLᵀ</code> buffers are laid out.</p><ul><li><p>Source: <a href="https://github.com/darnstrom/daqp" target="_blank" rel="noreferrer">https://github.com/darnstrom/daqp</a> (MIT)</p></li><li><p>Copyright: Daniel Arnström.</p></li></ul><p><a href="https://github.com/darnstrom/DAQP.jl" target="_blank" rel="noreferrer">DAQP.jl</a> is the wrapper around that C solver, and is what the benchmarks and the oracle tests compare against.</p><h2 id="PureIPM" tabindex="-1">PureIPM <a class="header-anchor" href="#PureIPM" aria-label="Permalink to &quot;PureIPM {#PureIPM}&quot;">​</a></h2><p><strong>MIT.</strong> Not a derivative either. The algorithm follows <a href="https://doi.org/10.1137/0802028" target="_blank" rel="noreferrer">On the implementation of a primal-dual interior point method</a> (Mehrotra, 1992).</p><p><a href="https://github.com/oxfordcontrol/Clarabel.jl" target="_blank" rel="noreferrer">Clarabel.jl</a> (Paul Goulart and Yuwen Chen) is the independent interior-point implementation used to validate it: iteration counts and objectives are compared against it across the benchmark suite. It is a reference for the answers, not a source for the code.</p><h2 id="Citing" tabindex="-1">Citing <a class="header-anchor" href="#Citing" aria-label="Permalink to &quot;Citing {#Citing}&quot;">​</a></h2><p>If you use the operator-splitting method in published work, please cite the OSQP papers:</p><p><strong>Main algorithm:</strong> <a href="https://doi.org/10.1007/s12532-020-00179-2" target="_blank" rel="noreferrer">OSQP: an operator splitting solver for quadratic programs</a> (Stellato et al., 2020).</p><p>For the interior-point method, cite Mehrotra (1992). For the active-set method, cite Arnström, Bemporad and Axehill (2022).</p><h2 id="Key-differences-from-libosqp" tabindex="-1">Key differences from libosqp <a class="header-anchor" href="#Key-differences-from-libosqp" aria-label="Permalink to &quot;Key differences from libosqp {#Key-differences-from-libosqp}&quot;">​</a></h2><p>libosqp 1.0 is the reference for <code>PureOSQP</code>: its settings, its defaults, and its termination and certificate tests. These are the differences from it.</p><ul><li><p>The inner KKT system is reduced to an <code>n×n</code> positive definite system.</p></li><li><p>The factored matrix is inverted in place for the dense case, making solves faster.</p></li><li><p>Equilibration is stored as factors and applied lazily, so <code>P</code> and <code>A</code> are never copied.</p></li><li><p>A backend is chosen from the declared types of <code>P</code> and <code>A</code>, so a structured matrix is solved through its structure rather than through its sparsity pattern.</p></li><li><p><code>ρ</code> has no wall-clock adaptation mode. Deciding when to refactorize by reading a clock makes the iteration count a property of the machine; the other three modes are all here.</p></li><li><p>Solution derivatives can be computed via implicit differentiation, and the element type is <code>Real</code> rather than a float, so dual numbers run the solver.</p></li><li><p>Errors are thrown, carrying their own messages, rather than returned as codes to look up with <code>osqp_error_message</code>.</p></li><li><p>There is no code generation.</p></li></ul>',30)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
